// Normalise the landing-page payload and reject obvious junk.
const clean = (v) => (typeof v === 'string' ? v.trim() : '');
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

// Disposable domains you do not want in the pipeline.
const BLOCKED_DOMAINS = ['mailinator.com', 'yopmail.com', 'guerrillamail.com', '10minutemail.com'];

return $input.all().map((item) => {
  const b = item.json.body ?? item.json;
  const meta = b.meta ?? {};
  const params = meta.params ?? {};

  const email = clean(b.email).toLowerCase();
  const domain = email.split('@')[1] || '';

  const errors = [];
  if (!clean(b.firstName)) errors.push('firstName');
  if (!clean(b.lastName)) errors.push('lastName');
  if (!EMAIL.test(email)) errors.push('email');
  if (!clean(b.company)) errors.push('company');
  if (!clean(b.businessType)) errors.push('businessType');
  if (BLOCKED_DOMAINS.includes(domain)) errors.push('email:disposable');

  // The browser never fills this; if it is set, it was a bot.
  if (clean(b.companyWebsite)) errors.push('honeypot');

  return {
    json: {
      valid: errors.length === 0,
      errors,
      lead: {
        firstName: clean(b.firstName),
        lastName: clean(b.lastName),
        fullName: clean(b.fullName) || `${clean(b.firstName)} ${clean(b.lastName)}`.trim(),
        email,
        emailDomain: domain,
        company: clean(b.company),
        countryCode: clean(b.countryCode),
        dialCode: clean(b.dialCode),
        phone: clean(b.phoneE164) || clean(b.phone),
        businessType: clean(b.businessType),
        heardFrom: clean(b.heardFrom) || 'Not answered',
        source: clean(b.source),
        formId: clean(b.formId),
        utmSource: params.utm_source ?? '',
        utmMedium: params.utm_medium ?? '',
        utmCampaign: params.utm_campaign ?? '',
        utmContent: params.utm_content ?? '',
        utmTerm: params.utm_term ?? '',
        gclid: params.gclid ?? '',
        fbclid: params.fbclid ?? '',
        referrer: meta.referrer ?? '',
        pageUrl: meta.pageUrl ?? '',
        locale: meta.locale ?? '',
        timezone: meta.timezone ?? '',
        screen: meta.screen ?? '',
        userAgent: meta.userAgent ?? '',
        fillMs: meta.fillMs ?? null,
        suspiciouslyFast: meta.suspiciouslyFast === true,
        submittedAt: meta.submittedAt ?? new Date().toISOString()
      }
    }
  };
});

