const deviceFrom = (ua) => {
  if (!ua) return '';
  if (/iPad|Tablet/i.test(ua)) return 'Tablet';
  if (/Mobi|Android|iPhone/i.test(ua)) return 'Mobile';
  return 'Desktop';
};

return $input.all().map((item) => {
  const L = item.json.lead;

  // Match the naming already used in this table: "Company - Contact Name".
  const name = L.company ? `${L.company} - ${L.fullName}` : L.fullName;

  const [countryName, countryOption] = COUNTRIES[L.countryCode] || ['', ''];

  const fields = [
    { id: F.contactName,  value: L.fullName },
    { id: F.email,        value: L.email },
    { id: F.companyName,  value: L.company },
    { id: F.companyType,  value: L.businessType },

    // This column identifies WHICH FORM a lead came from — existing rows hold
    // "GetSiteControl Visitor Form" and "Meta Lead Form", not the visitor's answer.
    { id: F.heardFrom,    value: FORM_NAME },

    // ...so the visitor's own answer goes in Source, next to the "fb" that
    // the Meta automation writes there.
    { id: F.source,       value: L.heardFrom },

    { id: F.leadCreated,  value: Date.parse(L.submittedAt) || Date.now() }
  ];

  if (L.phone)        fields.push({ id: F.contactPhone, value: L.phone });
  if (countryName)    fields.push({ id: F.countryText,  value: countryName });
  if (countryOption)  fields.push({ id: F.countryDrop,  value: countryOption });
  if (CHANNEL_OPTION) fields.push({ id: F.channel,      value: CHANNEL_OPTION });

  // 📣 Campaign Name / 📣 Ad Name and ⚙️ Device are deliberately NOT written:
  // the first two hold Meta Ads campaign/ad names and writing organic utm values
  // there would corrupt ad reporting; ⚙️ Device belongs to onboarding, not to the
  // browser someone filled a form in. All of it is in the description instead.

  const description = [
    `There is a new lead from ${FORM_NAME}:`,
    '',
    `Business type : ${L.businessType}`,
    `Heard about us: ${L.heardFrom}`,
    `Phone         : ${L.phone || '—'}`,
    `Country       : ${countryName || L.countryCode || '—'}`,
    `Device Info   : ${deviceFrom(L.userAgent) || '—'}`,
    '',
    `Page      : ${L.pageUrl || '—'}`,
    `Referrer  : ${L.referrer || 'direct'}`,
    `UTM       : source=${L.utmSource || '—'} medium=${L.utmMedium || '—'} campaign=${L.utmCampaign || '—'}`,
    L.gclid ? `gclid     : ${L.gclid}` : false,
    L.fbclid ? `fbclid    : ${L.fbclid}` : false,
    `Locale/TZ : ${L.locale || '—'} / ${L.timezone || '—'}`,
    `Submitted : ${L.submittedAt}`,
    L.suspiciouslyFast ? '\n⚠️ Submitted suspiciously fast — may be a bot.' : false
  ].filter((l) => l !== false).join('\n');

  return {
    json: {
      lead: L,
      clickup: {
        name,
        description,
        status: 'new',
        custom_item_id: LEAD_TASK_TYPE,   // create it as a "Lead", like every other row
        tags: ['contact request', 'landing page'],
        custom_fields: fields
      }
    }
  };
});
